cases.good:
window.addEventListener('resize', reposition);
window.addEventListener('orientationchange', reposition);
// ResizeObserver detects clientWidth change when scrollbar appears/disappears
// — no 'resize' event fires because window size is unchanged.
if (typeof ResizeObserver !== 'undefined') {
  const ro = new ResizeObserver(() => reposition());
  ro.observe(document.documentElement);
  return () => ro.disconnect();
}

cases.bad:
// Luôn dùng clientWidth — trong fullscreen clientWidth có thể stale
function resolveViewport() {
  return { width: document.documentElement?.clientWidth || window.innerWidth };
}

cases.good:
// Fullscreen: innerWidth (no scrollbar, clientWidth may be stale)
// Normal: clientWidth (excludes scrollbar, badge flush with scrollbar left edge)
function resolveViewport(viewport?: ViewportRect): ViewportRect {
  if (viewport) return viewport;
  if (document.fullscreenElement) {
    return { width: window.innerWidth, height: window.innerHeight };
  }
  return {
    width: document.documentElement?.clientWidth || window.innerWidth,
    height: document.documentElement?.clientHeight || window.innerHeight
  };
}

